FUNCTION_BLOCK FB
VAR_INPUT
    cyclicExecution : BOOL;
    trigger : BOOL;
    value : LREAL;
    windowSize : INT;
    reset : BOOL;
END_VAR
VAR_OUTPUT
    average : LREAL;
    windowSizeReached : BOOL;
    error : BOOL;
    status : WORD;
END_VAR
VAR
    buffer : ARRAY [0..99] OF LREAL;
    count : INT := 0;
    writeIndex : INT := 0;
    lastTrigger : BOOL := FALSE;
    rising : BOOL;
    sum : LREAL;
    i : INT;
    startIndex : INT;
    validRead : BOOL;
    firstScan : BOOL := TRUE;
    oldCount : INT;
END_VAR

// 首次扫描初始化
IF firstScan THEN
    count := 0;
    writeIndex := 0;
    average := 0.0;
    windowSizeReached := FALSE;
    firstScan := FALSE;
END_IF

// 计算 trigger 上升沿
rising := trigger AND NOT lastTrigger;

// 设置错误状态与状态码
IF (windowSize < 1) OR (windowSize > 100) THEN
    error := TRUE;
    status := 16#8200;
ELSE
    error := FALSE;
    status := 16#0000;
END_IF

// 复位处理（优先级最高）
IF reset THEN
    count := 0;
    writeIndex := 0;
    average := 0.0;
    windowSizeReached := FALSE;
    lastTrigger := trigger;  // 防止复位解除后误触发
ELSE
    // 只有在窗口合法时才进行数据处理
    IF NOT error THEN
        // 处理窗口尺寸变化（截断到新窗口大小并立即更新平均）
        IF count > windowSize THEN
            count := windowSize;
            -- 重新计算平均和窗口满标志
            IF count > 0 THEN
                sum := 0.0;
                startIndex := (writeIndex - count + 100) MOD 100;
                FOR i := 0 TO count - 1 DO
                    sum := sum + buffer[(startIndex + i) MOD 100];
                END_FOR;
                average := sum / INT_TO_LREAL(count);
                windowSizeReached := (count >= windowSize);
            ELSE
                average := 0.0;
                windowSizeReached := FALSE;
            END_IF;
        END_IF;

        -- 判断是否有读取请求
        IF cyclicExecution THEN
            validRead := TRUE;
        ELSE
            validRead := rising;
        END_IF;

        IF validRead THEN
            -- 写入新样本
            buffer[writeIndex] := value;
            writeIndex := (writeIndex + 1) MOD 100;
            IF count < windowSize THEN
                count := count + 1;
            END_IF;

            -- 重新计算平均
            IF count > 0 THEN
                sum := 0.0;
                startIndex := (writeIndex - count + 100) MOD 100;
                FOR i := 0 TO count - 1 DO
                    sum := sum + buffer[(startIndex + i) MOD 100];
                END_FOR;
                average := sum / INT_TO_LREAL(count);
            ELSE
                average := 0.0;
            END_IF;

            -- 更新窗口满标志
            IF count >= windowSize THEN
                windowSizeReached := TRUE;
            ELSE
                windowSizeReached := FALSE;
            END_IF;
        END_IF;
    END_IF;
END_IF;

// 更新 lastTrigger
lastTrigger := trigger;

END_FUNCTION_BLOCK
